using UnityEngine;
public sealed class EndlessChunkSpawner:MonoBehaviour{[SerializeField]Transform player;[SerializeField]GameObject[] chunks;[SerializeField]float chunkLength=30f;[SerializeField]int visible=8;int next;float z;void Start(){z=player.position.z;for(int i=0;i<visible;i++)Spawn();}void Update(){if(player.position.z+visible*chunkLength>z)Spawn();}void Spawn(){if(chunks==null||chunks.Length==0)return;Instantiate(chunks[next%chunks.Length],new Vector3(0,0,z),Quaternion.identity);next++;z+=chunkLength;}}